        d.fillStyle = "#DDE6F5";
        d.beginPath();
        d.arc(x, y, r, 0, Math.PI * 2);
        d.fill();
    }
    d.globalAlpha = 1;
}
function artCloudPath(d, cx, cy, s) {
    d.beginPath();
