        d.moveTo(52, 56);
        d.lineTo(40, 78);
        d.lineTo(50, 78);
        d.lineTo(44, 96);
        d.lineTo(64, 70);
        d.lineTo(53, 70);
        d.lineTo(60, 56);
        d.closePath();
        d.fill();
    }
