            d.moveTo(34 + i * 16, 66);
            d.lineTo(28 + i * 16, 86);
            d.stroke();
        }
    }
    else if (kind == "sunset" || kind == "sunrise") {
        d.fillStyle = "#FFD34D";
        d.beginPath();
        d.arc(50, 58, 20, Math.PI, 0);
        d.closePath();
        d.fill();
        d.strokeStyle = "#F4F7FB";
        d.lineWidth = 5;
        d.lineCap = "round";
        d.beginPath();
        d.moveTo(16, 62);
        d.lineTo(84, 62);
        d.stroke();
        d.beginPath();
        const up = kind == "sunrise";
        d.moveTo(50, up ? 40 : 22);
        d.lineTo(50, up ? 22 : 40);
        d.moveTo(42, up ? 30 : 32);
        d.lineTo(50, up ? 22 : 40);
        d.lineTo(58, up ? 30 : 32);
        d.stroke();
    }
    d.restore();
}
